}

Instructional content:
{
  "hook": {
    "duration_minutes": 3,
    "activity": "Întrebare: Cum ar calcula un robot pretul a 3 ciocolate dacă una costa 5 lei? Noi știm: 3 x 5 = 15. Dar robotul (calculatorul) are nevoie de instrucțiuni clare - operatori! Astazi transformam matematica în cod Scratch.",
    "connection_to_prior": "Lectia trecuta am învățat să cream variabile. Acum învățăm să facem CALCULE cu valorile din variabile!"
  },
  "micro_lecture": {
    "duration_minutes": 10,
    "key_terms": [
      {
        "term": "Operator aritmetic",
        "definition": "Un bloc care face o operație matematica cu doua numere",
        "analogy": "E ca semnele +, -, x, : de la matematica, dar în forma de piesa de puzzle"
      },
      {
        "term": "Expresie",
        "definition": "O combinatie de numere, variabile și operatori care da un rezultat",
        "analogy": "E ca o formula matematica: (nota1 + nota2) / 2"
      },
      {
        "term": "Adunare (+)",
        "definition": "Blocul verde cu + care aduna doua valori",
        "analogy": "5 + 3 da 8 - exact ca la matematica"
      },
      {
        "term": "Scadere (-)",
        "definition": "Blocul verde cu - care scade a doua valoare din prima",
        "analogy": "10 - 4 da 6"
      },
      {
        "term": "Inmultire (*)",
        "definition": "Blocul verde cu * care inmulteste doua valori",
        "analogy": "3 * 7 da 21"
      },
      {
        "term": "Impartire (/)",
        "definition": "Blocul verde cu / care imparte prima valoare la a doua",
        "analogy": "20 / 4 da 5"
      },
      {
        "term": "Modulo (rest)",
        "definition": "Blocul care da restul impartirii - util să verifici dacă un numar e par sau impar",
        "analogy": "7 modulo 3 = 1 (pentru ca 7 = 2*3 + 1)"
      }
    ],
    "explain_like_im_12": "Ganditi-va la operatori ca la instrumente de calcul. Dacă vreau să știu cat costa 5 mere la 2 lei bucata, am nevoie de inmultire: 5 * 2. Dacă vreau să impart 100 de bomboane la 4 prieteni, am nevoie de impartire: 100 / 4. În Scratch, aceste calcule sunt blocuri verzi pe care le imbini ca piesele de puzzle.",
    "visual_aids": [
      "Tabel cu operatorii și simbolurile lor: + - * / mod",
      "Captura Scratch: categoria Operatori cu blocurile verzi",
      "Exemplu vizual: expresie (a + b) * 2 cu blocuri imbricate"
    ]
  },
  "practice_guided": {
    "duration_minutes": 15,
    "tasks": [
      {
        "task": "Primul calcul simplu",
        "steps": [
          "Deschide Scratch și creează un proiect nou",
          "Trage 'când se da click pe steag'",
          "Adaugă 'spune [Salut!] timp de [2] secunde'",
          "Din Operatori, trage blocul [() + ()] în locul 'Salut!'",
          "Scrie 5 în primul spațiu și 3 în al doilea",
          "Testeaza - pisica trebuie să spuna '8'"
        ],
        "teacher_support": "Demonstreaza cum blocul rotund intra în spatiul de text"
      },
      {
        "task": "Calcul cu variabile",
        "steps": [
          "Creează doua variabile: 'numar1' și 'numar2'",
          "La steag verde, seteaza numar1 la 10 și numar2 la 4",
          "Adaugă 'spune' cu blocul [numar1 - numar2]",
          "Testeaza - pisica trebuie să spuna '6'",
          "Schimbă operatorul în inmultire (*) și testeaza din nou"
        ],
        "teacher_support": "Arată cum se trag variabilele în blocul operator"
      },
      {
        "task": "Expresie complexa - calculul mediei",
        "steps": [
          "Creează variabile 'nota1' și 'nota2'",
          "Seteaza nota1 la 8 și nota2 la 6",
          "Pentru medie, avem nevoie de (nota1 + nota2) / 2",
          "Trage blocul de impartire [() / ()]",
          "În primul spațiu, pune blocul de adunare [nota1 + nota2]",
          "În al doilea spațiu, scrie 2",
          "Pune totul în 'spune' - pisica trebuie să spuna '7'"
        ],
        "teacher_support": "Explică ordinea: mai întâi adunarea (interior), apoi impartirea (exterior)"
      }
    ],
    "success_criteria": [
      "Elevul poate folosi un operator simplu (+, -, *, /)",
      "Elevul poate combina operatori cu variabile",
      "Elevul poate construi o expresie cu doi operatori imbricati"
    ]
  },
  "practice_independent": {
    "duration_minutes": 15,
    "levels": {
      "minim": [
        {
          "task": "Creează un program în care pisica spune rezultatul inmultirii a doua numere: 7 * 8. Apoi schimbă numerele și testeaza din nou.",
          "expected_output": "Pisica spune 56, apoi alt rezultat corect"
        }
      ],
      "standard": [
        {
          "task": "Creează un 'calculator de perimetru' pentru un dreptunghi. Variabile: 'lungime' = 10, 'latime' = 5. Pisica spune perimetrul folosind formula: 2 * (lungime + latime).",
          "expected_output": "Pisica spune 30 (perimetrul corect)"
        }
      ],
      "performanta": [
        {
          "task": "Creează un convertor Celsius -> Fahrenheit. Variabilă 'celsius' = 20. Formula: fahrenheit = celsius * 9 / 5 + 32. Pisica spune: 'X grade Celsius sunt Y grade Fahrenheit'.",
          "expected_output": "Pisica spune '20 grade Celsius sunt 68 grade Fahrenheit'"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Care sunt cei 4 operatori aritmetici de baza?"
      ],
      "standard": [
        "Cum calculezi media a doua note în Scratch? Scrie expresia cu blocuri."
      ],
      "performanta": [
        "De ce ordinea operatorilor conteaza? Da un exemplu unde (a + b) * c e diferit de a + b * c."
      ]
    },
    "preview_next": "Saptamana viitoare învățăm operatorii de comparatie: cum verificăm dacă un numar e mai mare, mai mic sau egal cu altul!"
  }
}

